    assert Arrays.equals(solution.leafSimilar(new int[]{5,3,8,1,4,7,9,null,2,6,null,null,null,null,null,null,null}, new int[]{5,3,8,1,4,7,9,null,2,6,null,null,null,null,null,null,null}), True);
    assert Arrays.equals(solution.leafSimilar(new int[]{5,1,4,null,2,null,3}, new int[]{5,1,3,null,2,null,4}), False);
    assert Arrays.equals(solution.leafSimilar(new int[]{1,2,3,4,5,6,7,null,null,null,null,null,8}, new int[]{1,2,3,4,5,7,6,null,null,null,null,null,8}), False);
    assert Arrays.equals(solution.leafSimilar(new int[]{3,5,1,6,2,9,8,null,null,7,4,10,11,12,13,14,15}, new int[]{3,5,1,6,2,9,8,null,null,7,4,10,11,12,13,14,15}), True);
    assert Arrays.equals(solution.leafSimilar(new int[]{5,1,5,5,null,5,null,5,5,null,5}, new int[]{5,5,1,null,5,5,null,5,5,null,5}), True);
    assert Arrays.equals(solution.leafSimilar(new int[]{1,2,null,3,null,4,null,5}, new int[]{1,2,null,4,null,3,null,5}), True);
    assert Arrays.equals(solution.leafSimilar(new int[]{1,null,2,null,3,null,4,null,5}, new int[]{1,2,3,4,5}), False);
    assert Arrays.equals(solution.leafSimilar(new int[]{1,2,3,4,null,5,null,null,6}, new int[]{1,2,3,null,5,4,null,null,null,6}), False);
    assert Arrays.equals(solution.leafSimilar(new int[]{4,3,null,1,2}, new int[]{4,3,null,2,1}), False);
